package com.papeleria.pos.util;

import org.junit.jupiter.api.Test;
import java.time.LocalDateTime;

import static org.junit.jupiter.api.Assertions.*;

public class DateUtilTest {

    @Test
    void testFromDbStringWithSpace() {
        // This is the exact format generated by SQLite datetime('now')
        String dbDate = "2026-10-10 05:26:32";
        LocalDateTime dt = DateUtil.fromDbString(dbDate);
        assertNotNull(dt);
        assertEquals(2026, dt.getYear());
        assertEquals(10, dt.getMonthValue());
        assertEquals(10, dt.getDayOfMonth());
        assertEquals(5, dt.getHour());
        assertEquals(26, dt.getMinute());
        assertEquals(32, dt.getSecond());
    }

    @Test
    void testFromDbStringWithT() {
        String dbDate = "2026-10-10T05:26:32";
        LocalDateTime dt = DateUtil.fromDbString(dbDate);
        assertNotNull(dt);
        assertEquals(2026, dt.getYear());
        assertEquals(10, dt.getMonthValue());
        assertEquals(10, dt.getDayOfMonth());
    }

    @Test
    void testFromDbStringWithMilliseconds() {
        String dbDate = "2026-10-10 05:26:32.456";
        LocalDateTime dt = DateUtil.fromDbString(dbDate);
        assertNotNull(dt);
        assertEquals(2026, dt.getYear());
    }

    @Test
    void testFromDbStringDateOnly() {
        String dbDate = "2026-10-10";
        LocalDateTime dt = DateUtil.fromDbString(dbDate);
        assertNotNull(dt);
        assertEquals(2026, dt.getYear());
        assertEquals(0, dt.getHour());
    }

    @Test
    void testFromDbStringNullOrBlank() {
        assertNull(DateUtil.fromDbString(null));
        assertNull(DateUtil.fromDbString("   "));
    }

    @Test
    void testFromDbStringInvalidFallback() {
        LocalDateTime dt = DateUtil.fromDbString("invalid-date-string");
        assertNotNull(dt, "Should fallback gracefully rather than throwing exception");
    }
}

